from datetime import date
from typing import Dict

class Loyalty:
    def __init__(self) -> None:
        # Initialize a dictionary to store customer data
        self.customers: Dict[str, Dict[date, int]] = {}

    def purchase(self, customer: str, amount: float, day: date) -> int:
        """Record a purchase; returns the number of points earned."""
        if amount <= 0:
            raise ValueError("Purchase amount must be greater than zero")

        # Calculate points earned
        points_earned = int(amount // 10)

        # Initialize customer data if not existing
        if customer not in self.customers:
            self.customers[customer] = {}

        # Update customer points
        if day not in self.customers[customer]:
            self.customers[customer][day] = points_earned
        else:
            self.customers[customer][day] += points_earned

        return points_earned

    def balance(self, customer: str, day: date) -> int:
        """Points the customer can spend on the given day."""
        if customer not in self.customers or day not in self.customers[customer]:
            return 0

        return self.customers[customer][day]

    def redeem(self, customer: str, points: int, day: date) -> None:
        """Redeem points."""
        if points % 100 != 0:
            raise ValueError("Points can only be redeemed in multiples of 100")

        if points > self.balance(customer, day):
            raise ValueError("Not enough points to redeem")

        if points <= 0:
            raise ValueError("Points to redeem must be greater than zero")

        self.customers[customer][day] -= points

# Example usage:
if __name__ == "__main__":
    loyalty = Loyalty()
    print(loyalty.purchase("John Doe", 100.0, date(2024, 1, 1)))  # Output: 10
    print(loyalty.balance("John Doe", date(2024, 1, 1)))  # Output: 10
    loyalty.redeem("John Doe", 100, date(2024, 1, 1))
    print(loyalty.balance("John Doe", date(2024, 1, 1)))  # Output: 0
```

